<?php require 'admin_guard.php'; require 'admin_db.php'; $code=$_GET['coursecode']??$_POST['coursecode']??'';$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']);$desc=trim($_POST['description']);$credit=(float)$_POST['credit'];$mark=(float)$_POST['total_mark'];$s=mysqli_prepare($conn,'UPDATE course SET name=?,description=?,credit=?,total_mark=? WHERE coursecode=?');mysqli_stmt_bind_param($s,'ssdds',$name,$desc,$credit,$mark,$code);$msg=mysqli_stmt_execute($s)?'Course updated successfully.':'Update failed.';}
$s=mysqli_prepare($conn,'SELECT * FROM course WHERE coursecode=?');mysqli_stmt_bind_param($s,'s',$code);mysqli_stmt_execute($s);$c=mysqli_fetch_assoc(mysqli_stmt_get_result($s));if(!$c)die('Course not found'); ?>
<!doctype html><html><head><title>Update Course</title><link rel="stylesheet" href="admin_pages.css"></head><body><div class="page"><div class="panel"><h1>Update Course <?=htmlspecialchars($code)?></h1><?php if($msg)echo'<div class="notice">'.htmlspecialchars($msg).'</div>';?><form method="post"><input type="hidden" name="coursecode" value="<?=htmlspecialchars($code)?>"><label>Course Name</label><input name="name" value="<?=htmlspecialchars($c['name'])?>" required><label>Description</label><textarea name="description" required><?=htmlspecialchars($c['description'])?></textarea><label>Credit</label><input name="credit" type="number" step=".01" value="<?=$c['credit']?>" required><label>Total Mark</label><input name="total_mark" type="number" value="<?=$c['total_mark']?>" required><button>Update</button></form></div></div></body></html>
